 "content": "from collections import Counter


def transform(grid):
    """Mark background-colored cells that differ between repeated row-blocks."""
    out = [row[:] for row in grid]
    if not grid or not grid[0]:
        return out
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    w = len(grid[0])
    # Repeated objects are contiguous bands of rows that contain non-background
    # cells, separated by the solid background field.
    bands = []
    start = None
    for i, row in enumerate(grid):
        active = any(v != bg for v in row)
        if active and start is None:
            start = i
        elif not active and start is not None:
            bands.append((start, i))
            start = None
    if start is not None:
        bands.append((start, len(grid)))

    for a in range(len(bands)):
        a0, a1 = bands[a]
        ha = a1 - a0
        for b in range(a + 1, len(bands)):
            b0, b1 = bands[b]
            if b1 - b0 != ha:
                continue
            total = ha * w
            diffs = sum(grid[a0 + r][c] != grid[b0 + r][c]
                        for r in range(ha) for c in range(w))
            # Copies may contain a modest number of added/omitted cells.
            if not diffs or diffs / total > 0.40:
                continue
            for r in range(ha):
                for c in range(w):
                    va, vb = grid[a0 + r][c], grid[b0 + r][c]
                    if va != vb:
                        if va == bg:
                            out[a0 + r][c] = 1
                        if vb == bg:
                            out[b0 + r][c] = 1
    return out
